import{_ as r,a0 as p,w as l,s as u,I as t,x as o,a1 as i,A as n,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"理查德·斯托曼经典语录集锦 | LCTT x X-CMD","titleTemplate":false,"description":"理查德·斯托曼经典语录集锦 | LCTT (201602) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"理查德·斯托曼经典语录集锦 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"理查德·斯托曼经典语录集锦 | LCTT (201602) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201602/20151020 30 Years of Free Software Foundation--Best Quotes of Richard Stallman","title":"理查德·斯托曼经典语录集锦","tag":"201602","desc":""},"relativePath":"201602/20151020 30 Years of Free Software Foundation--Best Quotes of Richard Stallman.md","filePath":"[post].md"}'),d={name:"201602/20151020 30 Years of Free Software Foundation--Best Quotes of Richard Stallman.md"};function h(g,e,m,c,b,f){const s=p("Link");return l(),u("div",null,[e[23]||(e[23]=t("h1",{id:"理查德·斯托曼经典语录集锦",tabindex:"-1"},[o("理查德·斯托曼经典语录集锦 "),t("a",{class:"header-anchor",href:"#理查德·斯托曼经典语录集锦","aria-label":"Permalink to “理查德·斯托曼经典语录集锦”"},"​")],-1)),e[24]||(e[24]=t("p",null,"注：youtube 视频",-1)),e[25]||(e[25]=t("iframe",{width:"660",height:"495",src:"https://www.youtube.com/embed/aIL594DTzH4?feature=oembed",frameborder:"0",allowfullscreen:""},null,-1)),t("p",null,[e[2]||(e[2]=t("strong",null,"理查德·马修·斯托曼（Richard Matthew Stallman）",-1)),e[3]||(e[3]=o(" (RMS) – 神级程序员之一。他是一名程序员，是 GCC、GDB、Emacs 的构建者，软件自由的传教士，",-1)),i(s,{href:"http://www.gnu.org/"},{default:n(()=>[...e[0]||(e[0]=[o("GNU Project",-1)])]),_:1}),e[4]||(e[4]=o(" 和 ",-1)),i(s,{href:"http://www.fsf.org/"},{default:n(()=>[...e[1]||(e[1]=[o("FSF",-1)])]),_:1}),e[5]||(e[5]=o(" 的创办人。",-1))]),e[26]||(e[26]=a('<p><strong>GNU</strong> 是 “GNU’s Not Unix!”的递归缩写。GNU 是一系列用于基于 Unix 的操作系统的自由软件集合。它能用于 GNU/Hurd 和 Linux 内核。于1983年9月27日公诸于众。常用组件有：</p><ul><li>GNU Compiler Collection (GCC)</li><li>GNU C library (glibc)</li><li>GNU Core Utilities (coreutils)</li><li>GNU Debugger (GDB)</li><li>GNU Binary Utilities (binutils)</li><li>GNU Bash shell</li><li>GNOME desktop environment</li></ul><p>注：视频 <video src="//static.fsf.org/nosvn/FSF30-video/FSF_30_720p.webm" controls="controls" width="640" height="390"></video></p>',3)),t("p",null,[e[7]||(e[7]=t("strong",null,"自由软件基金会（Free Software Foundation）",-1)),e[8]||(e[8]=o(" (FSF) – 一个自由软件的非营利组织，致力于推进计算机用户的自由和捍卫他们的权力。于 1985年10月4日成立。阅读",-1)),i(s,{href:"https://www.fsf.org/about/"},{default:n(()=>[...e[6]||(e[6]=[o("更多",-1)])]),_:1}),e[9]||(e[9]=o("。",-1))]),e[27]||(e[27]=a("<p>许多人不理解开源代码（open source code）和自由软件（free software）的区别。每个程序都应该是自由软件：</p><ul><li>与目的无关，随心运行程序的自由（自由0）。</li><li>学习程序如何运作，并改变它为你所用的自由（自由1）。可以访问源码是这一条的前提。</li><li>重新发布副本的自由，如此你便可以帮助你周围的人（自由 2）。</li><li>发布自己修改版本给他人的自由（自由 3）。这样能让整个社区有机会从你的改变中受益。可以访问源码是这条的前提。</li></ul><p>以上为自由软件的四项自由原则。</p><p>以下为理查德·斯托曼关于自由、软件、社交、哲学等方面的名言摘引。</p><p><strong>关于 Facebook：</strong></p><blockquote><p>Facebook is not your friend, it is a surveillance engine.</p></blockquote><p>Facebook 不是你的朋友，是监控引擎。</p><p><strong>关于 Android：</strong></p><blockquote><p>Android is very different from the GNU/Linux operating system because it contains very little of GNU. Indeed, just about the only component in common between Android and GNU/Linux is Linux, the kernel.</p></blockquote><p>Android 和 GNU/Linux 有很大的区别，因为其中几乎没有 GNU。的确，Android 和 GNU/Linux 之间仅有一个共同组件，那就是内核 - Linux。</p><p><strong>关于计算机行业：</strong></p><blockquote><p>The computer industry is the only industry that is more fashion-driven than women&#39;s fashion.</p></blockquote><p>计算机行业是唯一一个比女性时尚业更容易受潮流影响的行业了。</p><p><strong>关于云计算：</strong></p><blockquote><p>The interesting thing about cloud computing is that we&#39;ve redefined cloud computing to include everything that we already do.</p></blockquote><p>关于云计算，有趣的是我们已经重新定义了云计算来包含我们曾干过的所有事。</p><p><strong>关于伦理：</strong></p><blockquote><p>Whether gods exist or not, there is no way to get absolute certainty about ethics. Without absolute certainty, what do we do? We do the best we can.</p></blockquote><p>无论神存在与否，都没有绝对的伦理道德。没有这份理所当然，我们该如何？也唯有尽善吧。</p><p><strong>关于自由：</strong></p><blockquote><p>Free software is software that respects your freedom and the social solidarity of your community. So it&#39;s free as in freedom.</p></blockquote><p>自由软件是尊重个人自由和社会团结的软件。所以才能如自由般自由自在。</p><p><strong>关于目标和理想：</strong></p><blockquote><p>If you want to accomplish something in the world, idealism is not enough - you need to choose a method that works to achieve the goal.</p></blockquote><p>如果你想为这世界做些什么，仅有理想是不够的，你需要找条通往目标的道路并走完。</p><p><strong>关于分享：</strong></p><blockquote><p>Sharing is good, and with digital technology, sharing is easy.</p></blockquote><p>分享很棒，而且数字化技术也使分享变得容易。</p><p><strong>关于 facebook（进阶版）：</strong></p><blockquote><p>Facebook mistreats its users. Facebook is not your friend; it is a surveillance engine. For instance, if you browse the Web and you see a &#39;like&#39; button in some page or some other site that has been displayed from Facebook. Therefore, Facebook knows that your machine visited that page.</p></blockquote><p>Facebook 蹂躏它们的用户。它不是你们的朋友；它就是个监控引擎。举个例子，你是否曾在一些网页或网站上看到 Facebook 的 “like” 按键。对，Facebook 知道你的电脑曾访问过那些网页。</p><p><strong>关于 web 应用：</strong></p><blockquote><p>One reason you should not use web applications to do your computing is that you lose control.</p></blockquote><p>给你个为什么不应该使用 web 应用的理由，因为你失去了计算机的控制权。</p><blockquote><p>If you use a proprietary program or somebody else&#39;s web server, you&#39;re defenceless. You&#39;re putty in the hands of whoever developed that software.</p></blockquote><p>如果你使用私有程序或他人的 web 服务器，那么你只能任人鱼肉。被软件的开发者轻易操纵。</p><p><strong>关于书：</strong></p><blockquote><p>With paper printed books, you have certain freedoms. You can acquire the book anonymously by paying cash, which is the way I always buy books. I never use a credit card. I don&#39;t identify to any database when I buy books. Amazon takes away that freedom.</p></blockquote><p>印刷出来的书，当然是自由的。你可以付现金匿名买书，这也是我一直买书的方式。我绝不会使用信用卡，我买书时不会被任何数据库记下。是亚马逊把自由夺走了。</p><p><strong>关于 MPAA：</strong></p><blockquote><p>Officially, MPAA stands for Motion Picture Association of America, but I suggest that MPAA stands for Malicious Power Attacking All.</p></blockquote><p>MPAA 其实是美国电影协会（Motion Picture Association of America），但我认为叫做攻击万物的邪恶力量（Malicious Power Attacking All）更为合适。</p><p><strong>关于金钱与职业：</strong></p><blockquote><p>I could have made money this way, and perhaps amused myself writing code. But I knew that at the end of my career, I would look back on years of building walls to divide people, and feel I had spent my life making the world a worse place.</p></blockquote><p>我可以找份工作赚钱，并沉浸在编码的快乐中。但在职业生涯结束后，回首目睹自己筑就的高墙将人与人分隔开，我会觉得我耗尽毕生精力只换来了一个更糟糕的世界。</p><p><strong>关于私有软件：</strong></p><blockquote><p>Proprietary software keeps users divided and helpless. Divided because each user is forbidden to redistribute it to others, and helpless because the users can&#39;t change it since they don&#39;t have the source code. They can&#39;t study what it really does. So the proprietary program is a system of unjust power.</p></blockquote><p>私有软件使用户孤立、无助。因为禁止将软件给他人使用所以孤立，因为无法改变源码所以无助。他们不能学习其中真正的工作方式，所以整个私有软件体系就是一种不公的力量。</p><p><strong>关于智能手机：</strong></p><blockquote><p>A smartphone is a computer - it&#39;s not built using a computer - the job it does is the job of being a computer. So, everything we say about computers, that the software you run should be free - you should insist on that - applies to smart phones just the same. And likewise to those tablets.</p></blockquote><p>智能手机就是电脑 —— 虽然做的和常用的电脑不同 —— 但是却能干电脑能干的活。所以我们所说的一切有关于电脑上的软件应该能自由运行 —— 必须坚持这一点 —— 在智能手机上也是这样，当然也包括平板。</p><p><strong>关于 CD 和数字内容：</strong></p><blockquote><p>CD stores have the disadvantage of an expensive inventory, but digital bookshops would need no such thing: they could write copies at the time of sale on to memory sticks, and sell you one if you forgot your own.</p></blockquote><p>CD 商店有一个弱势就是需要昂贵的库存，但是电子商店就没有这方面的需求：他们只需要将售卖的副本写入记忆棒，并在你忘带自己的记忆棒时卖你一个就是了。</p><p><strong>关于竞争范式（paradigm of competition）：</strong></p><blockquote><p>The paradigm of competition is a race: by rewarding the winner, we encourage everyone to run faster. When capitalism really works this way, it does a good job; but its defenders are wrong in assuming it always works this way.</p></blockquote><p>竞争范式就像是赛跑：奖励胜者，鼓励每一个跑得更快的人。当资本主义真的这样运作时，当然是件好事；但是维护它的人若是假设它一直这样运作的话那就大错特错了。</p><p><strong>关于 vi 和 emacs：</strong></p><blockquote><p>People sometimes ask me if it is a sin in the Church of Emacs to use vi. Using a free version of vi is not a sin; it is a penance. So happy hacking.</p></blockquote><p>有时会有人问我在 Emacs 的阵营使用 vi 是不是一种罪过。使用自由版的 vi 并不是一种罪过；是一种自我惩罚。所以好好享受其中乐趣吧。</p><p><strong>关于自由和历史：</strong></p><blockquote><p>Value your freedom or you will lose it, teaches history. &#39;Don&#39;t bother us with politics&#39;, respond those who don&#39;t want to learn.</p></blockquote><p>历史告诉我们不珍惜自由便失去自由，然而有的人不懂吸取教训，只知道说“别拿政治烦我们”。</p><p><strong>关于专利：</strong></p><blockquote><p>Fighting patents one by one will never eliminate the danger of software patents, any more than swatting mosquitoes will eliminate malaria.</p></blockquote><p>和专利一个一个的战斗并不能解决软件专利带来的危害，就像打再多的蚊子也消灭不了疟疾一样。</p><blockquote><p>Software patents are dangerous to software developers because they impose monopolies on software ideas.</p></blockquote><p>软件专利对于软件的开发者来说十分危险，因为它们加剧了对于软件理念的垄断。</p><p><strong>关于版权：</strong></p><blockquote><p>In practice, the copyright system does a bad job of supporting authors, aside from the most popular ones. Other authors&#39; principal interest is to be better known, so sharing their work benefits them as well as readers.</p></blockquote><p>其实，版权制度对作者也没有什么好处，撇开最受欢迎的那个，其他作者的主旨可能更好理解，所以分享无论对他们还是你的读者都是一件好事。</p><p><strong>关于工作与报酬：</strong></p><blockquote><p>There is nothing wrong with wanting pay for work, or seeking to maximize one&#39;s income, as long as one does not use means that are destructive.</p></blockquote><p>劳有所得，或寻求收入的最大化并没有什么错，只要不是不择手段。</p><p><strong>关于 Chrome OS：</strong></p><blockquote><p>In essence, Chrome OS is the GNU/Linux operating system. However, it is delivered without the usual applications, and rigged up to impede and discourage installing applications.</p></blockquote><p>Chrome OS 确实是 GNU/Linux 的操作系统。但是，它在发布时没有安装常用应用，并为安装他们设置了阻碍。</p><p><strong>关于 Linux 用户：</strong></p><blockquote><p>Many users of the GNU/Linux system will not have heard the ideas of free software. They will not be aware that we have ideas, that a system exists because of ethical ideals, which were omitted from ideas associated with the term &#39;open source.&#39;</p></blockquote><p>许多的 GNU/Linux 用户并没有听过自由软件。他们并没有意识到，这个系统是因为道德理想才存在的，与此一起被忽视的还有所谓的“开源”。</p><p><strong>关于 facebook 的隐私：</strong></p><blockquote><p>If there is a Like button in a page, Facebook knows who visited that page. And it can get IP address of the computer visiting the page even if the person is not a Facebook user.</p></blockquote><p>如果页面上有 “like” 按键，Facebook 就能知道谁访问了页面。即使不是 Facebook 的用户，也可以得到访问该页面电脑的 IP 地址。</p><p><strong>关于编程：</strong></p><blockquote><p>Programming is not a science. Programming is a craft.</p></blockquote><p>编程不是科学，编程是手艺。</p><blockquote><p>My favorite programming languages are Lisp and C. However, since around 1992 I have worked mainly on free software activism, which means I am too busy to do much programming. Around 2008 I stopped doing programming projects.</p></blockquote><p>Lisp 和 C 语言是我的最爱。然自 1992 年以来我主要工作在自由软件活动上，导致我太忙了，没法做更多的编程。大概在 2008 年我便停止了做编程项目。</p><blockquote><p>C++ is a badly designed and ugly language. It would be a shame to use it in Emacs.</p></blockquote><p>C++ 设计的真糟糕、真丑陋。在 Emacs 上用它应该觉得羞愧。</p><p><strong>关于钻研（hacking）和学习编程：</strong></p><blockquote><p>People could no longer learn hacking the way I did, by starting to work on a real operating system, making real improvements. In fact, in the 1980s I often came across newly graduated computer science majors who had never seen a real program in their lives. They had only seen toy exercises, school exercises, because every real program was a trade secret. They never had the experience of writing features for users to really use, and fixing the bugs that real users came across. The things you need to know to do real work.</p></blockquote><p>(时过境迁，)人们没法再像我当初那样通过改进实实在在的操作系统来学习编程了。上世纪 80 年代，我常遇见计算机专业的毕业生，有生以来没见过真正的程序。他们接触的到的只有小玩意和学校的作业，因为每一个程序都是商业机密。他们没有机会为用户去写真正实用的特性，修复用户真正遭遇的问题。而这些正是真正的工作中你需要掌握的(东西)。</p><blockquote><p>It is hard to write a simple definition of something as varied as hacking, but I think what these activities have in common is playfulness, cleverness, and exploration. Thus, hacking means exploring the limits of what is possible, in a spirit of playful cleverness. Activities that display playful cleverness have &quot;hack value&quot;.</p></blockquote><p>对于如“hacking”这般多样化的东西真的很难简单的下定义，不过在我看来诸如此类的行为都会有以下的这些共同点：嬉乐、智慧和探索。因此，hacking 意味着对可能的极限的探索，一颗向往快乐与智慧的心。能带来快乐与智慧的行为就有 “hack 的价值” 。</p><p><strong>关于浏览网页：</strong></p><blockquote><p>For personal reasons, I do not browse the web from my computer. (I also have no net connection much of the time.) To look at page I send mail to a daemon which runs wget and mails the page back to me. It is very efficient use of my time, but it is slow in real time.</p></blockquote><p>出于个人原因，我不会在我的电脑上浏览网页。（大部分时间处于没有网络连接的状态。）要浏览网页，我需要给一个守护进程发 mail，然后它会运行 wget 并把页面通过 mail 发还给我。这对我而言已经是最效率了，但那真的比实时慢太多了。</p><p><strong>关于音乐共享：</strong></p><blockquote><p>Friends share music with each other, they don&#39;t allow themselves to be divided by a system that says that nobody is supposed to have copies.</p></blockquote><p>朋友之间彼此分享音乐，绝不会希望因为系统的一句：“禁止私下拷贝！”而生分。</p><hr>",102)),t("p",null,[e[11]||(e[11]=o("via: ",-1)),i(s,{href:"https://tlhp.cf/fsf-richard-stallman/"},{default:n(()=>[...e[10]||(e[10]=[o("https://tlhp.cf/fsf-richard-stallman/",-1)])]),_:1})]),t("p",null,[e[15]||(e[15]=o("作者：",-1)),i(s,{href:"https://tlhp.cf/fsf-richard-stallman/"},{default:n(()=>[...e[12]||(e[12]=[o("Pavlo Rudyi",-1)])]),_:1}),e[16]||(e[16]=o(" 译者：",-1)),i(s,{href:"https://github.com/martin2011qi"},{default:n(()=>[...e[13]||(e[13]=[o("martin2011qi",-1)])]),_:1}),e[17]||(e[17]=o(" 校对：",-1)),i(s,{href:"https://github.com/wxy"},{default:n(()=>[...e[14]||(e[14]=[o("wxy",-1)])]),_:1})]),t("p",null,[e[20]||(e[20]=o("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[18]||(e[18]=[o("LCTT",-1)])]),_:1}),e[21]||(e[21]=o(" 原创编译，",-1)),i(s,{href:"https://linux.cn/"},{default:n(()=>[...e[19]||(e[19]=[o("Linux中国",-1)])]),_:1}),e[22]||(e[22]=o(" 荣誉推出",-1))])])}const q=r(d,[["render",h]]);export{y as __pageData,q as default};
